import{_ as o,a0 as i,w as d,s as r,ao as t,I as l,a1 as e,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"通過編寫互動遊戲學習 Bash | LCTT x X-CMD","titleTemplate":false,"description":"通過編寫互動遊戲學習 Bash | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過編寫互動遊戲學習 Bash | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過編寫互動遊戲學習 Bash | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201208 Learn Bash by writing an interactive game","title":"通過編寫互動遊戲學習 Bash","tag":"202012","desc":""},"relativePath":"202012/20201208 Learn Bash by writing an interactive game.md","filePath":"[post].md"}'),u={name:"202012/20201208 Learn Bash by writing an interactive game.md"};function h(m,s,g,c,b,f){const n=i("Link");return d(),r("div",null,[s[25]||(s[25]=t('<h1 id="通過編寫互動遊戲學習-bash" tabindex="-1">通過編寫互動遊戲學習 Bash <a class="header-anchor" href="#通過編寫互動遊戲學習-bash" aria-label="Permalink to “通過編寫互動遊戲學習 Bash”">​</a></h1><blockquote><p>編程一個簡單的遊戲是練習一門新語言並與其他你掌握的語言進行比較的好方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/28/010432yq3vgsqtiol9zzi6.jpg" alt=""></p><p>學習一門新的編程語言是很有趣的。每當我嘗試學習一門新的語言時，我都會專注於定義變量、編寫語句和評估表達式。一旦我對這些概念有了大致的瞭解，我通常可以自己弄清楚其餘的概念。大多數編程語言都有一些相似之處，所以一旦你瞭解了一種編程語言，學習下一種編程語言就是要弄清楚其獨特的細節，認識到其中的差異。</p><p>為了幫助我練習一種新的編程語言，我喜歡寫一些測試程序。我經常寫的一個示例程序是一個簡單的“猜數字”程序，電腦在 1 到 100 之間選一個數字，讓我猜這個數字。程序會一直循環，直到我猜對為止。</p><p>“猜數字”程序鍛鍊了編程語言中的幾個概念：如何給變量賦值，如何寫語句，如何進行條件判斷和循環。對於學習一門新的編程語言來説，這是一個很好的實踐實驗。</p><h3 id="用-bash-猜數字" tabindex="-1">用 Bash 猜數字 <a class="header-anchor" href="#用-bash-猜數字" aria-label="Permalink to “用 Bash 猜數字”">​</a></h3>',7)),l("p",null,[e(n,{href:"https://en.wikipedia.org/wiki/Bash_(Unix_shell)"},{default:p(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[1]||(s[1]=a(" 是大多數 Linux 系統的標準 shell。除了提供豐富的命令列用户界面外，Bash 還以",-1)),s[2]||(s[2]=l("em",null,"腳本",-1)),s[3]||(s[3]=a("的形式支持完整的編程語言。",-1))]),s[26]||(s[26]=l("p",null,"如果你對 Bash 不熟悉，我推薦你看這些介紹：",-1)),l("ul",null,[l("li",null,[e(n,{href:"https://opensource.com/resources/what-bash"},{default:p(()=>[...s[4]||(s[4]=[a("什麼是 Bash？",-1)])]),_:1}),s[5]||(s[5]=a("。",-1))]),l("li",null,[e(n,{href:"https://opensource.com/article/20/4/bash-programming-guide"},{default:p(()=>[...s[6]||(s[6]=[a("開始使用 Bash 編程",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/article/20/4/bash-sysadmins-ebook"},{default:p(()=>[...s[7]||(s[7]=[a("系統管理員的 Bash 腳本入門",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/article/20/6/bash-functions"},{default:p(()=>[...s[8]||(s[8]=[a("如何在 Bash 中編寫函數",-1)])]),_:1})]),l("li",null,[e(n,{href:"https://opensource.com/tags/bash"},{default:p(()=>[...s[9]||(s[9]=[a("閲讀更多關於 Bash 的信息",-1)])]),_:1})])]),s[27]||(s[27]=t(`<p>你可以通過編寫一個 Bash 版本的“猜數字”遊戲來探索它。這是我的實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>number=$(( $RANDOM % 100 + 1 ))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>guess=0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while [ &quot;0$guess&quot; -ne $number ] ; do</span></span>
<span class="line"><span>        read guess</span></span>
<span class="line"><span>        [ &quot;0$guess&quot; -lt $number ] &amp;&amp; echo &quot;Too low&quot;</span></span>
<span class="line"><span>        [ &quot;0$guess&quot; -gt $number ] &amp;&amp; echo &quot;Too high&quot;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><h3 id="拆解這個腳本" tabindex="-1">拆解這個腳本 <a class="header-anchor" href="#拆解這個腳本" aria-label="Permalink to “拆解這個腳本”">​</a></h3><p>腳本中的第一行，<code>#!/bin/bash</code> 告訴 Linux 使用 Bash shell 來運行這個腳本。每個腳本都以 <code>#!</code> 字符對（LCTT 譯註：釋伴）開始，這表示它是一個 shell 腳本。緊跟在<code>#!</code> 後面的是要運行的 shell。在本例中，<code>/bin/bash</code> 是指 Bash shell。</p><p>要給一個變量賦值，在變量名後面列出 <code>=</code> 號。例如，語句 <code>guess=0</code> 給 <code>guess</code> 變量分配一個零值。</p><p>你也可以使用 <code>read</code> 語句提示用户輸入一個值。如果你寫了 <code>read guess</code> 語句，Bash 會等待用户輸入一些文本，然後把這個值存儲在 <code>guess</code> 變量中。</p><p>要引用一個變量的值，在變量名前使用 <code>$</code>。所以, 在 <code>guess</code> 變量中存儲了一個值後, 你可以使用 <code>$guess</code> 來檢索它。</p><p>你可以使用任何你喜歡的變量名稱，但是 Bash 為自己保留了一些特殊的變量名稱。一個特殊的變量是 <code>RANDOM</code>，每次引用它都會產生一個很大的隨機數。</p><p>如果你想在存儲一個值的同時執行一個操作，你需要用特殊的括號把語句括起來。這將告訴 Bash 先執行該語句，而 <code>=</code> 則將結果值存儲在變量中。要評估一個數學表達式，使用 <code>$(())</code> 圍在你的語句上。雙括號表示一個<em>算術表達式</em>。在我的例子中，<code>number=$(( $RANDOM % 100 + 1 ))</code> 評估表達式 <code>$RANDOM % 100 + 1</code>，然後將值存儲在 <code>number</code> 變量中。</p><p>標準的算術運算符，如 <code>+</code>（加）、<code>-</code>（減）、<code>*</code>（乘）、<code>/</code>（除）和 <code>%</code>（模）都適用。</p><p>這意味着語句 <code>number=$(( $RANDOM % 100 + 1 ))</code> 產生一個 1 到 100 之間的隨機數。模數運算符（<code>%</code>）返回兩個數相除後的餘數。在這種情況下，Bash 將一個隨機數除以 100，剩下的餘數範圍是 0 到 99，通過在這個值上加 1，你可以得到一個介於 1 和 100 之間的隨機數。</p><p>Bash 支持像循環這樣的<em>條件表達式</em>和<em>流程控制</em>。在“猜數字”的遊戲中，只要 <code>guess</code> 中的值不等於 <code>number</code>，Bash 就會繼續循環。如果猜的數小於隨機數，Bash 就會打印“太低”，如果猜的數大於數字，Bash 就會打印“太高”。</p><h3 id="它是如何工作的" tabindex="-1">它是如何工作的 <a class="header-anchor" href="#它是如何工作的" aria-label="Permalink to “它是如何工作的”">​</a></h3><p>現在你已經寫好了你的 Bash 腳本，你可以運行它來玩“猜數字”遊戲。一直猜，直到你找到正確的數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>30</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>20</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>14</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>每次運行這個腳本，Bash 都會隨機選擇一個不同的數字。</p><p>這個“猜數字”遊戲是學習新的編程語言時的一個很好的入門程序，因為它以一種很直接的方式鍛鍊了幾個常見的編程概念。通過在不同的編程語言中實現這個簡單的遊戲，你可以展示一些核心概念，並比較每種語言的細節。</p><p>你有喜歡的編程語言嗎？你會如何用它來寫“猜數字”遊戲呢？請關注本系列文章，看看你可能感興趣的其他編程語言的例子。</p><hr>`,19)),l("p",null,[s[11]||(s[11]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/12/learn-bash"},{default:p(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/20/12/learn-bash",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:p(()=>[...s[12]||(s[12]=[a("Jim Hall",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const x=o(u,[["render",h]]);export{k as __pageData,x as default};
